/** Fast ICAO lookup via Map */
const AIRPORT_MAP = new Map<string, Airport>(AIRPORTS.map(a => [a.icao, a]));

/** Look up an airport by ICAO code */
export function findAirport(icao: string): Airport | undefined {
  return AIRPORT_MAP.get(icao.toUpperCase());
}

/** Search airports by ICAO prefix or name substring */
export function searchAirports(query: string, limit = 8): Airport[] {
  const q = query.toUpperCase().trim();
  if (!q) return [];
  // ICAO prefix matches first, then name/city matches
  const icaoMatches: Airport[] = [];
  const nameMatches: Airport[] = [];
  for (const a of AIRPORTS) {
    if (icaoMatches.length + nameMatches.length >= limit) break;
    if (a.icao.startsWith(q)) {
      icaoMatches.push(a);
    } else if (a.name.toUpperCase().includes(q) || a.city.toUpperCase().includes(q)) {
      nameMatches.push(a);
    }
  }
  return [...icaoMatches, ...nameMatches].slice(0, limit);
}
